SELECT *, SUM(humidity) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_humidity, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY status_bits, id) AS seq_no, AVG(status_bits) OVER (PARTITION BY device_code ORDER BY temp_c, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS status_bits_avg_6_prior FROM device_readings;
